var apiUtils = require("@node-red/editor-api/lib/util");
var fs = require("fs");
var runtime;
var utilApi = require("@node-red/util");
const { set } = require("grunt");



var api = module.exports = {
    init: function (_runtime) {
        runtime = _runtime;
    },

    /**
     * Sets the flow context using key 'parents' to store child-parent dictionary
     * 
     * The child-parent dictionary keys are ids of the child nodes. Each key(child nod) refreneces an array containing a list of parent ids. Example: 
     * { [child_id]: [parent_id1,parent_id2]}
     * @param {Object} req Request object from UI containg the child-parent dictionary
     * @param {*} res Response object
     * */
    test: function (req, res) {
        res.send(200)
    },
    set_context: async function set_context(req, res) {
        try {
            var pc_idx = req.body.pc_idx
            Object.keys(pc_idx).forEach(nodeID => {
                // console.log("----------------------------------")
                node = runtime._.nodes.getNode(nodeID)
                ctx_flow = node.context()["flow"]
                if (ctx_flow.get("parents")) {
                    prev_idx = ctx_flow.get("parents")
                    if (JSON.stringify(prev_idx) !== JSON.stringify(pc_idx)) {
                        ctx_flow.set("parents", pc_idx)
                    }
                } else {
                    utilApi.log.info("[GEMINOS] Setting the context of the flow: node.context()['flow'] ")
                    ctx_flow.set("parents", pc_idx)
                }
            })
            // runtime.causeway.set_context("parent", nodeID, pc_idx)
            res.send("Successfuly retrieved context")
        } catch (exception) {
            console.log(exception)
            res.send(exception)
        }
    },

    /**
     * Finds all backdoors in the current flow 
     * @param {*} req Request object containing id of the flow 
     * @param {*} res 
     */
    model_annotations: async function model_annotations(req, res) {
        utilApi.log.info("[GEMINOS] Retrieving flow context for node id: " + JSON.stringify(req.body))
        var flow = runtime._.flows.getFlow(req.body.id)
        var node = runtime._.nodes.getNode(flow.nodes[0].id)
        var ctx_flow = node.context()["flow"]
        var child_parent = ctx_flow.get("parents")

        // mark colliders by inserting collider property
        Object.keys(child_parent).forEach(key => {
            if ((child_parent[key]).length > 1) {
                console.log("child has " + child_parent[key].length + " parents")
                var child_node = runtime._.nodes.getNode(key)
                console.log(key, ": ", child_node)
                // inserting prop
                var parents = child_parent[key]
                child_node["collider"] = { v: true, parents: parents }
                console.log(child_node)
            }
        })
    },

    check_collider: async function check_collider(req, res) {
        console.log("check collider")
    },

    find_backdoors: async function find_backdoors(req, res) {
        let parent_child_idx = req.body.parent_child
        let treatments = req.body.treatments

        let outcome = req.body.outcomes
        console.log(outcome[0])
        let backdoors = []
        let links = {}
        let set = []
        let backdoor_set = ""

        const result = new Promise((resolve, reject) => {
            for (index in treatments) {
                if (parent_child_idx[treatments]) {
                    console.log("arrows going into treatment: ", parent_child_idx[treatments])
                    //  check wires of parents to see if goes into outcome
                    parent_child_idx[treatments].forEach(parent => {
                        let parent_node = runtime._.nodes.getNode(parent)
                        console.log("========= [ Treatment parent ", parent_node.name, " ] ============")
                        backdoor_set = check_parent(treatments[index], parent_node, outcome[0])
                        backdoors = Object.assign({}, backdoors, backdoor_set)
                    });
                }
                else {
                    console.log("no backdoors to account for")
                }
            }

            resolve(backdoors)
        });
        console.log("--here -- ")
        result.then(backdoors => {
            if (Object.keys(backdoors).length > 0) {
                console.log("backdoors:", backdoors)
                res.send(backdoors)
            } else {
                res.send("no backdoors")
            }
        })

    }
}



/**
 * Checks to see if path exists to outcome from current node
 * @param {*} node 
 * @param {*} outcome 
 */
function dfs(node, treatment, outcome, backdoors) {
    let set = []
    if (node.wires[0].length > 0) {
        console.log("==" + node.name)
        node.wires[0].forEach(wire => {
            if (wire === outcome) {
                console.log(node.name + " => " + outcome)
                set.push([node.id, outcome])
                backdoors.push([node.id, outcome])
                return true
            }
            if (wire !== treatment) {
                let new_node = runtime._.nodes.getNode(wire)
                console.log("new node name: ", new_node.name)
                let path_to_outcome = dfs(new_node, treatment, outcome, backdoors)
                if (path_to_outcome) {
                    backdoors.push([node.id, wire])
                }
                return path_to_outcome
            }
        })
    } else {
        console.log("no wires ", node)
        return false
    }
    return true
}
function check_parent(treatment, parent_node, outcome) {
    let backdoors = {}
    if (parent_node) {
        let backdoors_temp = []
        dfs(parent_node, treatment, outcome, backdoors_temp)
        backdoors_temp.forEach(item => {
            console.log(item)
            backdoors = { ...backdoors, [item]: true }
        })
    }
    return backdoors
}

